use crate::legacy_pic::{PlaneQuartic,PicClass,Pt};
use hec_native_ic::{fp::Fp,poly::Poly,rng::Rng,solve::{Row,SolveStats,Solver,solve_for_last}};
use std::collections::HashMap;
pub struct Base{points:Vec<Pt>,conics:Vec<Vec<u64>>,ids:HashMap<Pt,usize>,rows:Vec<(Row,u64)>,pub lines:usize,pub split_lines:usize,pub relation_pic_cost:crate::legacy_pic::FqCounter,pub pair_trials:usize,pub rank:usize,pub p0_index:usize,pub certificates:Vec<(Pt,Vec<(usize,usize)>)>,pub native_delta:hec_native_ic::counted::Counts}
fn form(terms:&[(usize,i64)],ell:u64)->Row{let f=Fp::new(ell);let mut m=std::collections::BTreeMap::new();for &(i,c)in terms{let v=m.entry(i).or_insert(0);*v=f.add(*v,f.from_i64(c));}m.into_iter().filter(|(_,v)|*v!=0).map(|(i,v)|(i as u32,v)).collect()}
fn line_polynomial(pc:&PlaneQuartic,line:Pt,f:&Fp)->(Poly,Pt){let(u,v)=if line[0]!=0{([f.neg(line[1]),1,0],[f.neg(line[2]),0,1])}else if line[1]!=0{([1,0,0],[0,f.neg(line[2]),1])}else{([1,0,0],[0,1,0])};let coords=(0..3).map(|i|Poly::from_coeffs(&[v[i],u[i]])).collect::<Vec<_>>();let mut p=Poly::zero();for(&(i,j,k),&a)in crate::legacy_pic::mons_of_degree(4).iter().zip(pc.coefficients()){let mut t=Poly::constant(a);for(axis,n)in[i,j,k].iter().enumerate(){for _ in 0..*n{t=t.mul(&coords[axis],f);}}p=p.add(&t,f);}assert!(!p.is_zero());(p,pc.normalize_point(u))}
struct Ranker{pivots:Vec<Option<Vec<u64>>>,rank:usize}
impl Ranker{fn new(n:usize)->Self{Self{pivots:vec![None;n],rank:0}}fn insert(&mut self,row:&Row,f:&Fp)->bool{let n=self.pivots.len();let mut v=vec![0;n];for &(i,c)in row{v[i as usize]=c;}for i in 0..n{if v[i]==0{continue;}if let Some(ref r)=self.pivots[i]{let k=v[i];for j in i..n{if r[j]!=0{v[j]=f.sub(v[j],f.mul(k,r[j]));}}}else{let z=f.inv(v[i]);for j in i..n{if v[j]!=0{v[j]=f.mul(v[j],z);}}self.pivots[i]=Some(v);self.rank+=1;return true;}}false}fn rows(&self)->Vec<(Row,u64)>{self.pivots.iter().filter_map(|r|r.as_ref().map(|r|(r.iter().enumerate().filter(|(_,v)|**v!=0).map(|(i,&v)|(i as u32,v)).collect(),0))).collect()}}
pub fn relation_rank(rows:Vec<Row>,n:usize,ell:u64)->usize{let mut rank=Ranker::new(n);let f=Fp::new(ell);for r in rows{rank.insert(&r,&f);}rank.rank}
fn norm(p:Pt,f:&Fp)->Pt{let z=f.inv(*p.iter().find(|&&v|v!=0).unwrap());p.map(|v|f.mul(v,z))}
fn secant(p:Pt,q:Pt,f:&Fp)->Pt{norm([f.sub(f.mul(p[1],q[2]),f.mul(p[2],q[1])),f.sub(f.mul(p[2],q[0]),f.mul(p[0],q[2])),f.sub(f.mul(p[0],q[1]),f.mul(p[1],q[0]))],f)}
fn parameter(p:Pt,line:Pt,f:&Fp)->Option<u64>{if line[0]!=0{if p[2]==0{None}else{Some(f.mul(p[1],f.inv(p[2])))}}else if line[1]!=0{if p[2]==0{None}else{Some(f.mul(p[0],f.inv(p[2])))}}else if p[1]==0{None}else{Some(f.mul(p[0],f.inv(p[1])))}}
fn point(t:u64,line:Pt,f:&Fp)->Pt{norm(if line[0]!=0{[f.neg(f.add(f.mul(line[1],t),line[2])),t,1]}else if line[1]!=0{[t,f.neg(line[2]),1]}else{[t,1,0]},f)}
fn residual_roots(p:&Poly,f:&Fp)->Option<Vec<(u64,usize)>>{match p.deg(){0=>Some(vec![]),1=>Some(vec![(f.mul(f.neg(p.c[0]),f.inv(p.c[1])),1)]),2=>{let discr=f.sub(f.mul(p.c[1],p.c[1]),f.mul(4,f.mul(p.c[2],p.c[0])));let r=f.sqrt(discr)?;let z=f.inv(f.mul(2,p.c[2]));let a=f.mul(f.sub(f.neg(p.c[1]),r),z);let b=f.mul(f.add(f.neg(p.c[1]),r),z);if a==b{Some(vec![(a,2)])}else{let mut out=vec![(a,1),(b,1)];out.sort();Some(out)}},_=>panic!("residual not quadratic")}}
pub fn build(pc:&PlaneQuartic,ell:u64,map:usize)->Base{let before=pc.counter();let native_before=hec_native_ic::counted::snapshot();let f=Fp::new(pc.q());let fl=Fp::new(ell);let points=pc.rational_points_bruteforce();assert_eq!(points.len(),66);let ids=points.iter().enumerate().map(|(i,&p)|(p,i)).collect::<HashMap<_,_>>();let conics=points.iter().map(|&p|pc.std_values(2,p)).collect();let p0=*ids.get(&pc.base_point()).unwrap();let mut rank=Ranker::new(points.len()+1);rank.insert(&vec![(p0 as u32,1)],&fl);let mut pairs=(0..points.len()).flat_map(|i|(0..i).map(move|j|(i,j))).collect::<Vec<_>>();assert_eq!(pairs.len(),2145);let mut rng=Rng::new(2026112500^map as u64);for i in(1..pairs.len()).rev(){let j=rng.below((i+1)as u64)as usize;pairs.swap(i,j);}let mut seen=std::collections::HashSet::new();let mut certificates=Vec::new();let mut pair_trials=0;for(i,j)in pairs{pair_trials+=1;let line=secant(points[i],points[j],&f);if !seen.insert(line){continue;}let(original,infinity)=line_polynomial(pc,line,&f);let mut p=original;let mut infinity_multiplicity=4-p.deg()as usize;let mut support=std::collections::BTreeMap::new();for id in[i,j]{*support.entry(id).or_insert(0usize)+=1;if let Some(t)=parameter(points[id],line,&f){assert_eq!(p.eval(t,&f),0);p=p.div_exact(&Poly::x_minus(t,&f),&f);}else{assert!(infinity_multiplicity>0);infinity_multiplicity-=1;}}assert_eq!(p.deg()as usize+infinity_multiplicity,2);let Some(roots)=residual_roots(&p,&f)else{continue;};if infinity_multiplicity>0{*support.entry(*ids.get(&infinity).unwrap()).or_insert(0)+=infinity_multiplicity;}for(t,m)in roots{let pt=point(t,line,&f);assert_eq!((0..3).fold(0,|s,k|f.add(s,f.mul(line[k],pt[k]))),0);*support.entry(*ids.get(&pt).unwrap()).or_insert(0)+=m;}let support=support.into_iter().collect::<Vec<_>>();assert_eq!(support.iter().map(|x|x.1).sum::<usize>(),4);let mut product=Poly::one();let mut missing=0;for &(id,m)in &support{if let Some(t)=parameter(points[id],line,&f){for _ in 0..m{product=product.mul(&Poly::x_minus(t,&f),&f);}}else{missing+=m;}}assert_eq!(original.monic(&f),product);assert_eq!(missing,4-original.deg()as usize);let mut terms=support.iter().map(|&(id,m)|(id,m as i64)).collect::<Vec<_>>();terms.push((points.len(),-1));let row=form(&terms,ell);let independent=rank.insert(&row,&fl);println!("SECANT map={map} coefficients={line:?} support={support:?} independent={independent} rank={}",rank.rank);certificates.push((line,support));if rank.rank==points.len(){break;}}
assert_eq!(rank.rank,66,"secant rank budget exhausted");let rows=rank.rows();let mut native_delta=hec_native_ic::counted::snapshot();for(k,values)in native_delta.iter_mut(){let old=native_before.get(k).copied().unwrap_or([0;16]);for i in 0..16{values[i]-=old[i];}}let lines=seen.len();let split_lines=certificates.len();println!("BASE map={map} points={} pair_trials={pair_trials} unique_lines={lines} split_lines={split_lines} retained_rank={} stored_rows={} exact_binary_factor_certificates=true",points.len(),rank.rank,rows.len());Base{points,conics,ids,rows,lines,split_lines,relation_pic_cost:pc.counter().since(&before),pair_trials,rank:rank.rank,p0_index:p0,certificates,native_delta}}
fn decompose(pc:&PlaneQuartic,x:&PicClass,base:&Base)->Option<Vec<(usize,i64)>>{match x{PicClass::Exc(p)=>Some(vec![(*base.ids.get(p)?, -1)]),PicClass::Typ(rows)=>{let f=Fp::new(pc.q());let roots=base.conics.iter().enumerate().filter(|(_,v)|rows.iter().all(|r|r.iter().zip(v.iter()).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b)))==0)).map(|(i,_)|i).collect::<Vec<_>>();if roots.len()!=3{return None;}let mut out=roots.into_iter().map(|i|(i,1)).collect::<Vec<_>>();out.push((base.points.len(),-1));Some(out)}}}
#[derive(Debug)]pub struct Report{pub k:u64,pub trials:usize,pub smooth:usize,pub relations:usize,pub solve_rounds:usize,pub solver:SolveStats,pub pic_cost:crate::legacy_pic::FqCounter}
pub fn solve(pc:&PlaneQuartic,g:&PicClass,t:&PicClass,ell:u64,base:&Base,seed:u64)->Option<Report>{let start=pc.counter();assert!(!pc.is_zero(g));assert!(ell*ell>9u64.pow(6));assert!(pc.is_zero(&pc.mul_scalar(g,ell as u128)));assert!(pc.is_zero(&pc.mul_scalar(t,ell as u128)));let mut rng=Rng::new(seed);let fl=Fp::new(ell);let mut x=pc.zero();let(mut a,mut b)=(0,0);let mut rows=base.rows.clone();let mut smooth=0;let mut rounds=0;let mut all_stats=SolveStats::default();for trial in 1..=4096{if rng.below(2)==0{x=pc.add(&x,g);a=fl.add(a,1);}else{x=pc.add(&x,t);b=fl.add(b,1);}let Some(mut terms)=decompose(pc,&x,base)else{continue;};smooth+=1;terms.push((base.points.len()+1,-(b as i64)));let row=form(&terms,ell);rows.push((row,a));rounds+=1;let mut stats=SolveStats::default();let k=solve_for_last(&rows,base.points.len()+1,ell,Solver::Fast,&[],&mut stats);all_stats.pivots+=stats.pivots;all_stats.row_ops+=stats.row_ops;all_stats.mulmods+=stats.mulmods;all_stats.max_row_len=all_stats.max_row_len.max(stats.max_row_len);all_stats.pivot_hash=stats.pivot_hash;if let Some(k)=k{assert_eq!(pc.mul_scalar(g,k as u128),*t,"quartic final verification failed");return Some(Report{k,trials:trial,smooth,relations:rows.len(),solve_rounds:rounds,solver:all_stats,pic_cost:pc.counter().since(&start)});}}None}
